import Ably from 'ably';

const client = new Ably.Realtime({ key: process.env.ABLY_API_KEY! });

// Subscribe to a channel
const channel = client.channels.get('live-scores');

await channel.subscribe('score-update', (message) => {
  const data = message.data as { team: string; score: number };
  console.log(`${data.team}: ${data.score}`);
});

// Publish an event
await channel.publish('score-update', {
  team: 'Team A',
  score: 3,
});

console.log('Subscribed and published');

import Ably from 'ably';

const client = new Ably.Realtime({ key: process.env.ABLY_API_KEY! });
const channel = client.channels.get('live-scores');

// Get last 50 messages from history
const historyPage = await channel.history({ limit: 50 });

for (const message of historyPage.items) {
  console.log(`[${message.timestamp}] ${message.name}:`, message.data);
}

// Check if there are more pages
if (historyPage.hasNext()) {
  const nextPage = await historyPage.next();
  console.log('More messages:', nextPage?.items.length);
}
